(n, m) = [int(i) for i in input().split(' ')]
g = []
(c, f) = (0, 0)
ans = ''

def row():
	global n, m, g, c, ans
	for i in range(n):
		t = min(g[i])
		c += t
		ans += 'row %d\n' % (i + 1) * t
		for j in range(m):
			g[i][j] -= t

def col():
	global n, m, g, c, ans
	for i in range(m):
		r = [_[i] for _ in g]
		t = min(r)
		c += t
		ans += 'col %d\n' % (i + 1) * t
		for j in range(n):
			g[j][i] -= t
for i in range(n):
	g.append([int(_) for _ in input().split(' ')])
if m >= n:
	row()
	col()
else:
	col()
	row()
for i in range(n):
	for j in range(m):
		if g[i][j] > 0:
			f = 1
			break
if f == 1:
	print(-1)
else:
	print(c)
	print(ans, end='')
